{
  "asyncapi": "3.0.0",
  "info": {
    "title": "Forecast Events",
    "version": "1.0.0",
    "description": "Synthetic demo events.",
    "x-audience": "internal"
  },
  "channels": {
    "forecastUpdated": {
      "address": "forecasts/{region}",
      "title": "Forecast updated",
      "parameters": {
        "region": {
          "description": "Region code."
        }
      },
      "messages": {
        "forecast": {
          "payload": {
            "type": "object",
            "properties": {
              "region": {
                "type": "string"
              }
            }
          }
        }
      }
    }
  },
  "operations": {
    "publishForecast": {
      "action": "send",
      "title": "Publish forecast",
      "channel": {
        "$ref": "#/channels/forecastUpdated"
      }
    }
  }
}
